-- Bangladesh schools, colleges and madrasahs with EIIN (BANBEIS institution list, via the
-- "Institutional Information of Bangladesh" dataset). Used to suggest a college while a student
-- fills in their profile.
CREATE TABLE "Institution" (
    "eiin" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "searchName" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "level" TEXT,
    "district" TEXT,
    "thana" TEXT,
    "division" TEXT,

    CONSTRAINT "Institution_pkey" PRIMARY KEY ("eiin")
);

CREATE INDEX "Institution_searchName_idx" ON "Institution"("searchName");

ALTER TABLE "Institution" ENABLE ROW LEVEL SECURITY;

